import {cabinet,rect,text,tile} from './cabinet.js';
export function toggleLights(b,i){const x=i%4,y=Math.floor(i/4);for(const [dx,dy] of [[0,0],[1,0],[-1,0],[0,1],[0,-1]]){const xx=x+dx,yy=y+dy;if(xx>=0&&xx<4&&yy>=0&&yy<4)b[yy*4+xx]^=1;}return b;}
export function lightPuzzle(level,random=Math.random){const b=Array(16).fill(0),available=Array.from({length:16},(_,i)=>i);for(let i=0;i<Math.min(3+level,12);i++){const k=Math.floor(random()*available.length);toggleLights(b,available.splice(k,1)[0]);}if(!b.some(Boolean))toggleLights(b,5);return b;}
export function createLights(mount,api){const q=cabinet(mount,api,{accent:'#e2ef85',height:440}),c=q.c;let level=1,board=lightPuzzle(1),moves=0,cursor=5,delay=0;
 function choose(i){if(!q.active||delay>0||i<0||i>=16)return;cursor=i;toggleLights(board,i);moves++;q.sound('toggle',board[i]?3:0);if(!board.some(Boolean)){q.add(Math.max(50,300-moves*8));q.burst(180,204);q.sound('clear');if(level===5){q.finish('A brilliant blackout.',`Five puzzles solved. ${q.score} points.`,true);}else{q.say('BLACKOUT! Next circuit…');delay=1;}}}
 return {start(){level=1;moves=0;board=lightPuzzle(level);delay=0;q.start();},tap(p){p=q.local(p);const x=Math.floor((p.x-20)/80),y=Math.floor((p.y-52)/80);if(x>=0&&x<4&&y>=0&&y<4)choose(y*4+x);},direction(d){cursor=Math.max(0,Math.min(15,cursor+({left:-1,right:1,up:-4,down:4}[d]||0)));},action(){choose(cursor);},tick(dt){q.frame(dt,dt=>{if(delay>0){delay-=dt;if(delay<=0){level++;moves=0;board=lightPuzzle(level);}}},()=>{q.header(`CIRCUIT ${level}/5`,`${moves} MOVES`);board.forEach((v,i)=>{const x=20+i%4*80,y=52+Math.floor(i/4)*80;tile(c,x+3,y+3,70,70,v?'#e2ef85':'#263644',v?'✦':'·',i===cursor);});text(c,'Tap flips a light and its + neighbors.',180,396,14,'#cad5df');q.footer('Turn every light off.');});},destroy:q.destroy};}
